import { useEffect, useState } from "react";

const TITLES: Record<string, string> = {
  "/": "Walk · Footwork",
  "/studio": "Soundprint · Footwork",
  "/about": "How it works · Footwork",
};

export function normalizePath(pathname: string): string {
  if (pathname.length > 1 && pathname.endsWith("/")) return pathname.slice(0, -1);
  return pathname;
}

export function useRoute(): {
  path: string;
  navigate: (event: { preventDefault: () => void; currentTarget: { href: string } }) => void;
} {
  const [path, setPath] = useState(() => normalizePath(window.location.pathname));

  useEffect(() => {
    const onPop = () => setPath(normalizePath(window.location.pathname));
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  useEffect(() => {
    document.title = TITLES[path] ?? "Footwork";
  }, [path]);

  const navigate = (event: { preventDefault: () => void; currentTarget: { href: string } }) => {
    event.preventDefault();
    const next = normalizePath(new URL(event.currentTarget.href).pathname);
    if (next !== window.location.pathname) {
      window.history.pushState(null, "", next);
    }
    setPath(next);
  };

  return { path, navigate };
}

type AppHeaderProps = {
  path: string;
  modeLabel: string;
  onNavigate: (event: { preventDefault: () => void; currentTarget: { href: string } }) => void;
};

const LINKS = [
  { href: "/", label: "Walk" },
  { href: "/studio", label: "Soundprint" },
  { href: "/about", label: "How it works" },
];

export function AppHeader({ path, modeLabel, onNavigate }: AppHeaderProps) {
  return (
    <header className="app-header">
      <a className="brand" href="/" onClick={onNavigate}>
        Footwork
      </a>
      <nav className="app-nav" aria-label="Primary">
        {LINKS.map((link) => (
          <a
            key={link.href}
            href={link.href}
            aria-current={path === link.href ? "page" : undefined}
            onClick={onNavigate}
          >
            {link.label}
          </a>
        ))}
      </nav>
      <p className="mode-badge">
        Mode <strong>{modeLabel}</strong>
      </p>
    </header>
  );
}

export function Notice({ errors }: { errors: string[] }) {
  return (
    <section className="notice" role="alert" aria-labelledby="fixture-error-title">
      <h1 id="fixture-error-title">The preview fixture failed validation</h1>
      <p>This screen is not showing a Soundprint. Reload after the fixture file is corrected.</p>
      <ul>
        {errors.slice(0, 8).map((error) => (
          <li key={error}>{error}</li>
        ))}
      </ul>
    </section>
  );
}

export function formatTime(ms: number): string {
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}:${seconds.toString().padStart(2, "0")}`;
}

import type { MovementEvent, RoutePoint } from "../contracts/types";

const EVENT_LABELS: Record<MovementEvent["type"], string> = {
  turn: "Turn",
  pause: "Pause",
  pace_change: "Pace change",
  loop: "Loop",
};

function pointAt(points: RoutePoint[], time: number): RoutePoint | null {
  let best: RoutePoint | null = null;
  let bestDelta = Number.POSITIVE_INFINITY;
  for (const point of points) {
    const delta = Math.abs(point.t_ms - time);
    if (delta < bestDelta) {
      best = point;
      bestDelta = delta;
    }
  }
  return best;
}

export function RouteFigure({ points, events }: { points: RoutePoint[]; events: MovementEvent[] }) {
  const poly = points.map((point) => `${point.x * 100},${point.y * 100}`).join(" ");
  const marks = events.filter((event) => event.type === "turn" || event.type === "pause");

  return (
    <figure className="route-figure">
      <svg viewBox="0 0 100 100" role="img" aria-labelledby="route-title route-desc">
        <title id="route-title">Synthetic route</title>
        <desc id="route-desc">
          A constructed path with a corner and a pause. It is not a map of a real place.
        </desc>
        <polyline className="route-path" points={poly} />
        {marks.map((event) => {
          const point = pointAt(points, event.audio_offset_ms);
          if (!point) return null;
          const cx = point.x * 100;
          const cy = point.y * 100;
          if (event.type === "pause") {
            return (
              <rect
                key={event.id}
                className="route-pause"
                x={cx - 2.2}
                y={cy - 2.2}
                width="4.4"
                height="4.4"
              >
                <title>{EVENT_LABELS[event.type]}</title>
              </rect>
            );
          }
          return (
            <circle key={event.id} className="route-turn" cx={cx} cy={cy} r="2.2">
              <title>{EVENT_LABELS[event.type]}</title>
            </circle>
          );
        })}
      </svg>
      <figcaption>
        Synthetic route. The line is the path. The circle is a turn and the square is a pause.
        Both musical mappings are planned, not heard.
      </figcaption>
    </figure>
  );
}

import type { DemoFixture, EventType } from "../contracts/types";
import { formatTime } from "./formatTime";
